import numpy as np
from scipy import ndimage as ndi
z=np.load('source_pixels.npz');print(z.files)
a=z[z.files[0]];print(a.shape,a.dtype)
f=a[0]; print('sample',[(p, f[p[1],p[0]].tolist()) for p in [(0,0),(128,72),(10,130),(128,130),(250,72)]])
# broad chromatic masks
for t in [0,12,24,48,72,95]:
