 for name,m in [('red',(r>g*1.4)&(r>b*1.4)&(r>65)),('green',(g>r*1.25)&(g>b*1.2)&(g>45)),('white',(np.min(f,2)>150)&(np.max(f,2)-np.min(f,2)<35))]:
